// Son ambiant continu — change avec l'état global de Luna
export interface AmbientLayer {
  readonly name:       string;
  readonly frequency:  number;    // Hz — tonique de base
  readonly gain:       number;    // 0.0–1.0
  readonly pulseRate:  number;    // Hz — vitesse de modulation d'amplitude
  readonly shape:      string;
}

export const AMBIENT_STATES = Object.freeze({

  actif: {
    base:    { name: "core",  frequency: 639, gain: 0.4, pulseRate: 1.0,  shape: "sine" },
    shimmer: { name: "high",  frequency: 741, gain: 0.15, pulseRate: 2.0, shape: "sine" },
  },

  latent: {
    base:    { name: "core",  frequency: 432, gain: 0.2, pulseRate: 0.3,  shape: "sine" },
    shimmer: { name: "low",   frequency: 396, gain: 0.08, pulseRate: 0.2, shape: "sine" },
  },

  instable: {
    base:    { name: "core",  frequency: 417, gain: 0.5, pulseRate: 4.5,  shape: "sawtooth" },
    shimmer: { name: "noise", frequency: 852, gain: 0.2, pulseRate: 7.0,  shape: "square"   },
  },

} as const);

// CanAmbient — au moins un OscillatorNode actif
export function canAmbient(activeOscillators: number): boolean {
  return activeOscillators > 0;
}

