#[derive(Debug, Clone)]
pub struct AmbientLayer {
    pub name:       &'static str,
    pub frequency:  f64,
    pub gain:       f64,
    pub pulse_rate: f64,
    pub shape:      &'static str,
}

pub const AMBIENT_ACTIF: &[AmbientLayer] = &[
    AmbientLayer { name: "core",  frequency: 639.0, gain: 0.40, pulse_rate: 1.0, shape: "sine" },
    AmbientLayer { name: "high",  frequency: 741.0, gain: 0.15, pulse_rate: 2.0, shape: "sine" },
];

